import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);
const sharp=require(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/sharp');
const root=path.resolve(import.meta.dirname,'..');
const out=path.join(root,'final');fs.mkdirSync(out,{recursive:true});
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
let parts=[],labels=[];
const ink='#18313A',muted='#51656D',paper='#FFFFFF';
function t(x,y,text,size=17,color=ink,weight=400,anchor='start'){
 labels.push(text);parts.push(`<text x="${x}" y="${y}" fill="${color}" font-family="DejaVu Sans" font-size="${size}" font-weight="${weight}" text-anchor="${anchor}">${esc(text)}</text>`);
}
function lines(x,y,arr,size=17,color=ink,weight=400,dy=23){arr.forEach((s,i)=>t(x,y+i*dy,s,size,color,weight));}
function rect(x,y,w,h,fill='none',stroke='none',r=0,sw=1){parts.push(`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`);}
function line(x1,y1,x2,y2,color='#A5B7BD',sw=1,dash=''){parts.push(`<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${sw}" ${dash?`stroke-dasharray="${dash}"`:''}/>`);}
function arrow(d,color='#287B79',dash=''){parts.push(`<path d="${d}" fill="none" stroke="${color}" stroke-width="2.4" ${dash?`stroke-dasharray="${dash}"`:''}/>`);let nums=d.match(/-?\d+(?:\.\d+)?/g).map(Number),x=nums.at(-2),y=nums.at(-1),px=nums.at(-4),py=nums.at(-3),a=Math.atan2(y-py,x-px),s=8;parts.push(`<path d="M${x} ${y}L${x-s*Math.cos(a-.45)} ${y-s*Math.sin(a-.45)}M${x} ${y}L${x-s*Math.cos(a+.45)} ${y-s*Math.sin(a+.45)}" fill="none" stroke="${color}" stroke-width="2.4"/>`);}
function circle(x,y,r,fill,stroke='none',sw=1){parts.push(`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`);}
function art(id,x,y,w,h){let b=fs.readFileSync(path.join(root,'art',id+'.png'));parts.push(`<image x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="xMidYMid meet" href="data:image/png;base64,${b.toString('base64')}"/>`);}
function begin(title,kicker,accent){parts=[];labels=[];rect(0,0,1200,630,paper);rect(36,31,6,49,accent);t(56,50,kicker,13,accent,700);t(56,87,title,30,ink,700);line(36,107,1164,107,'#DCE5E6');}
function footer(text,accent){line(36,572,1164,572,'#DCE5E6');t(36,602,text,15,accent,500);}
function section(x,y,caption,accent){t(x,y,caption,17,accent,700);line(x,y+10,x+175,y+10,accent,2);}
function box(x,y,w,h,title,subtitle,accent){rect(x,y,w,h,'#F5F9F9',accent,5,1.3);t(x+16,y+26,title,18,ink,700);if(subtitle)t(x+16,y+49,subtitle,14,muted);}
function wetlab(){const id='oct17-t1-autonomous-wet-lab',a='#167B78',b='#AD5D35';begin('Ground each action in live laboratory state','PHYSICAL AGENT SAFETY',a);
 art(id,24,137,398,385);t(44,536,'Conceptual laboratory workcell',13,muted);line(437,132,437,550,'#DCE5E6');
 section(465,143,'LIVE SEMANTIC TWIN',a);
 ['Robot geometry','Well volumes','Reagent identities','Pipette tip inventory'].forEach((s,i)=>{rect(465,167+i*50,226,41,i%2?'#F1F7F6':'#E7F2F0',undefined,2);circle(480,187+i*50,4,a);t(494,193+i*50,s,16);});
 line(703,182,703,339,a,2);line(693,182,703,182,a,2);line(693,339,703,339,a,2);
 box(752,131,241,61,'Proposed protocol','Agent plans laboratory actions',a);
 box(752,223,241,61,'Virtual dry run','Check geometry and resources',a);
 box(752,315,241,61,'Hardware check','Reject invalid commands',a);
 box(752,407,241,61,'Execute on robot','Only valid commands pass',a);
 arrow('M872 192 L872 218',a);arrow('M872 284 L872 310',a);arrow('M872 376 L872 402',a);
 arrow('M703 253 L744 253',a);arrow('M703 339 L727 339 L727 345 L744 345',a);
 arrow('M993 253 L1045 253 L1045 297',b);arrow('M993 345 L1045 345 L1045 325',b);
 rect(1011,298,147,29,'#F8E9E0',b,3);t(1084,318,'Block & replan',15,b,700,'middle');
 arrow('M1084 298 L1084 163 L1001 163',b,'5 4');
 rect(465,487,693,66,'#F3F7F7');t(481,511,'Synchronized video + action logs',18,a,700);t(481,536,'Inspect failures · preserve state · support recovery',15,ink);
 arrow('M993 439 L1117 439 L1117 478',a);
 footer('Physical measurements remain essential; scientific direction stays human.',a);return id;
}
function license(){const id='oct17-t2-license-aware-dependencies',a='#354F88',b='#A46B16';begin('Make dependency policy queryable before merge','LICENSE-AWARE CODING AGENTS',a);
 art(id,24,127,240,244);t(43,377,'Conceptual package assembly',12,muted);
 section(294,143,'ONE ENTERPRISE POLICY',a);
 rect(294,164,282,186,'#EDF1FA',a,6,1.5);t(313,193,'License policy',22,a,700);line(312,205,557,205,'#BCCAE0');
 ['Central license rules','Download / update APIs','Policy-change audit events'].forEach((s,i)=>{circle(318,229+i*41,4,a);t(332,234+i*41,s,15);if(i<2)line(313,246+i*41,557,246+i*41,'#CED9EA');});
 section(619,143,'AGENT PRE-CHECK',a);
 t(619,186,'Proposed dependency',19,ink,700);t(619,211,'Check package compliance',16,muted);
 arrow('M576 219 L607 219',a);arrow('M762 223 L762 251',a);
 line(667,259,1007,259,a,2);line(667,259,667,277,a,2);line(1007,259,1007,277,b,2);
 t(619,305,'Allowed candidate',17,a,700);t(619,330,'Can be recommended',15,muted);
 t(900,305,'Disallowed candidate',17,b,700);t(900,330,'Choose another package',15,muted);
 line(36,397,1164,397,'#DCE5E6');
 section(36,427,'PULL-REQUEST ENFORCEMENT',a);
 t(36,469,'New dependencies',17,ink,700);t(36,493,'Required ruleset check',15,muted);
 arrow('M236 481 L283 481',a);
 rect(291,447,259,82,'#EDF1FA',a,5);t(307,475,'License requirement',18,a,700);t(307,503,'Violation → PR annotation',15,muted);
 arrow('M434 350 L434 389 L562 389 L562 437 L467 437 L467 442',a);
 arrow('M550 470 L599 470',a);t(615,466,'Policy satisfied',18,a,700);t(615,491,'Other merge checks apply',15,muted);
 arrow('M550 516 L587 516 L587 546 L615 546',b);t(630,550,'Resolve violation',16,b,700);
 line(838,419,838,553,'#DCE5E6');t(859,437,'REVIEWABLE REMEDIES',15,b,700);
 lines(859,465,['Remove the dependency','Amend the license policy','Approve a package exception'],15,ink,400,25);
 t(859,551,'Closure: enterprise license manager',13,b,700);
 footer('Agent recommendations and pull requests share centralized license rules.',a);return id;
}
const selected=process.argv[2]||'wetlab';
function publicService(){const id='oct17-k1-public-service-workflows',a='#426E46',b='#A07823';begin('Keep public authority across the whole process','CONNECTED PUBLIC SERVICES',a);
 section(36,143,'MAINTENANCE EXAMPLE',a);
 const steps=[['Citizen','report'],['Assign','responsibility'],['Plan the','work'],['Resources','and budgets'],['Procure','if needed'],['Close','the case']];
 steps.forEach((s,i)=>{let x=46+i*186;circle(x+61,190,7,i===0?b:a);if(i<5)arrow(`M${x+71} 190 L${x+235} 190`,a);lines(x+61,223,s,17,ink,600,22);});
 line(36,267,1164,267,'#DCE5E6');
 art(id,25,275,370,242);t(45,500,'Conceptual civic setting',12,muted);
 rect(36,511,352,45,'#EDF3EB',a,3);t(51,530,'Sovereignty: data · operational',14,a,600);t(51,550,'technical · legal',14,a,600);
 section(430,303,'FUNDING APPLICATION EXAMPLE',a);
 rect(430,326,240,68,'#F2F6EF',a,5);t(445,351,'Submitted documents',17,a,700);t(445,377,'Eligibility + financial context',14,muted);
 arrow('M550 394 L550 419',a);rect(430,427,240,67,'#F2F6EF',a,5);t(445,453,'AI-assisted checking',18,a,700);t(445,478,'Completeness + consistency',15,muted);
 arrow('M670 462 L728 462',a);t(748,453,'Explained recommendation',18,ink,700);t(748,478,'Missing information flagged',16,muted);
 arrow('M955 487 L955 513',b);rect(744,520,408,34,'#FAF1DE',b,3);t(762,543,'Responsible public authority decides',17,b,700);
 t(748,351,'CONTROL + ACCOUNTABILITY',16,b,700);lines(748,378,['Keep data under defined sovereignty controls','Show employees the reasons for each flag'],14,muted,400,23);
 footer('Vendor demonstrations; independently measured service outcomes are unproven.',a);return id;
}
function quoting(){const id='oct17-k2-ericsson-quote-workflow',a='#A2513C',b='#305574';begin('Separate digital gains from agent exploration','CONTRACT-AWARE COMMERCIAL WORK',a);
 section(36,145,'EXISTING DIGITAL WORKFLOW',a);t(36,173,'Vendor-reported implementation',14,muted);
 ['Framework agreements','Contract-specific products','Negotiated pricing','Customer entitlements'].forEach((s,i)=>{rect(36+i*8,192+i*31,527-i*8,29,i%2?'#F9F0EB':'#F5E7DF');t(51+i*8,212+i*31,s,16,ink,500);});
 art(id,36,335,213,213);t(39,560,'Conceptual commercial folio',12,muted);
 arrow('M422 317 L422 346',a);t(290,373,'Self-service storefront',19,a,700);arrow('M418 386 L418 406',a);t(290,432,'Generate quote',18,ink,600);arrow('M418 444 L418 460',a);t(290,487,'Place order',18,ink,600);
 rect(278,510,310,44,'#F6E6DE',a,3);t(291,529,'Some requests: days or weeks',14,a,600);t(291,547,'become minutes or seconds',14,a,600);
 line(620,132,620,558,'#D2DDE2',2);t(654,145,'EXPLORATORY AGENT ASSISTANCE',17,b,700);line(654,155,1137,155,b,2);t(654,180,'Proposed capabilities under evaluation',14,muted);
 const ys=[224,294,364,434],title=['Analyze customer request','Find relevant contract terms','Prepare a proposed quote','Employee review and decision'];
 ys.forEach((y,i)=>{circle(670,y-7,5,b);t(689,y,title[i],18,i===3?b:ink,i===3?700:500);if(i<3)arrow(`M670 ${y+8} L670 ${ys[i+1]-22}`,b);});
 rect(654,477,498,77,'#EFF3F8',b,4);t(671,502,'Other exploratory uses',18,b,700);t(671,530,'Product descriptions · catalog search',16,muted);
 footer('Reported gains: digitization. Agent benefits remain unproven.',a);return id;
}
function skill(){const id='oct17-a1-quality-check-skill',a='#705590',b='#2A7564';begin('Package one quality procedure as a reviewable Skill','AGENT SKILLS',a);
 section(36,143,'PROCEDURE CONTENTS',a);section(779,143,'SUGGESTED READ-ONLY TRIAL',b);
 const labels0=[['Trigger','When this procedure applies'],['Test commands','Existing trusted project scripts'],['Lint commands','Established repository checks'],['Evidence meaning','What each command verifies'],['Failure guidance','Explain common failure modes']];
 labels0.forEach((pair,i)=>{let y=192+i*67;circle(43,y-6,4,a);t(59,y,pair[0],18,a,700);t(59,y+23,pair[1],15,muted);line(330,y-5,365,y-5,a,1.5);});line(365,187,365,455,a,1.5);
 rect(412,161,318,44,'#F2EEF7',a,4);t(571,189,'Quality-check Skill',22,a,700,'middle');line(365,321,404,321,a,2);
 art(id,407,223,326,295);t(436,536,'Conceptual procedure folio',13,muted);
 rect(779,173,177,57,'#EFF6F2',b,3);t(792,198,'Known-good case',16,b,600);t(792,217,'Baseline verification',12,muted);
 rect(974,173,177,57,'#EFF6F2',b,3);t(986,198,'Controlled failure',16,b,600);t(986,217,'Check error handling',12,muted);
 line(866,231,866,252,b,2);line(1062,231,1062,252,b,2);line(866,252,1062,252,b,2);arrow('M964 252 L964 275',b);
 t(779,300,'Record evidence',19,b,700);lines(779,328,['Command outputs','Exit results','Failure explanations'],16,ink,400,25);
 arrow('M964 391 L964 414',b);rect(779,422,372,40,'#EFF6F2',b,3);t(965,448,'PASS · REVIEW · STOP',19,b,700,'middle');
 arrow('M964 463 L964 487',b);t(779,515,'Human review before any repair',18,a,700);t(779,540,'Review the evidence and proposed change',14,muted);
 footer('Suggested boundary: existing commands, unchanged permissions, reviewed repairs.',a);return id;
}
function scorecard(){const id='oct17-a2-production-scorecard',a='#3E6287',b='#AF553B';begin('Define the scorecard before expanding agent authority','AGENT PRODUCTION READINESS',a);
 const xs=[36,424,812],heads=['Proof of concept','Minimum viable product','Production readiness'];
 const defs=[['Technical feasibility','Nonsensitive sandbox data'],['Core journeys end to end','Development data + user testing'],['Security + automated tests','Delivery + financial reviews']];
 xs.forEach((x,i)=>{rect(x,132,352,6,i===2?b:a);t(x,167,heads[i],21,i===2?b:a,700);lines(x,195,defs[i],15,muted,400,23);if(i<2)arrow(`M${x+358} 165 L${x+381} 165`,a);});
 line(36,245,1164,245,'#DCE5E6');
 art(id,27,271,288,262);t(39,547,'Conceptual staged progression',12,muted);
 t(339,282,'START WITH ONE OR TWO ACTIONS',17,a,700);t(339,308,'Set measurable criteria before the pilot',16,muted);
 const cx=[339,618,897],hn=['Quality','Operations','People + review'];
 const rr=[['Task completion','Hallucination rate','Verified test outcomes'],['Latency ceilings','Total ownership cost','Model drift + health'],['User acceptance testing','Time for edge cases','Sensitive-task review']];
 cx.forEach((x,i)=>{line(x,333,x+246,333,i===2?b:a,3);t(x,364,hn[i],20,i===2?b:a,700);rr[i].forEach((s,j)=>{circle(x+4,390+j*34,3,i===2?b:a);t(x+16,396+j*34,s,15);});});
 rect(339,488,813,67,'#EFF3F8',a,4);t(357,514,'Before broader autonomy',19,a,700);t(357,539,'Evaluate continuously · monitor costs · test fallback behavior',16,ink);
 footer('Start narrow; expand only after reviewed evidence.',a);return id;
}
const id=({wetlab,license,publicService,quoting,skill,scorecard})[selected]();
const svg=`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1200" height="630" viewBox="0 0 1200 630">${parts.join('')}</svg>`;
fs.writeFileSync(path.join(out,id+'.svg'),svg);
await sharp(Buffer.from(svg)).flatten({background:'#FFFFFF'}).png({compressionLevel:9,palette:false}).toFile(path.join(out,id+'.png'));
const bytes=fs.readFileSync(path.join(out,id+'.png'));
const metadata=await sharp(bytes).metadata();
const record={story_id:id,labels,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),git_blob_sha:crypto.createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex'),bytes:bytes.length,width:metadata.width,height:metadata.height,channels:metadata.channels,method:'native_conceptual_editorial_art_plus_separately_authored_exact_diagram'};
fs.writeFileSync(path.join(out,id+'.render.json'),JSON.stringify(record,null,2)+'\n');console.log(JSON.stringify(record,null,2));
